class KVCache:
    """KV cache for UltraQuant.

    The cache is a 2D array of slots, each slot holding a (token, head)
    pair. Each slot is 272 B for D=256, 136 B for D=128.

    The cache is initialized with a constant scale factor `c` and a
    group size `gs`. The group size is fixed at 32 because the AMD
    scaled F8F6F4 MFMA instruction also consumes one E8M0 scale per 32
    elements along K. Other group sizes would force a fallback to plain
    MFMA + accumulator-side scale multiply (no hardware fast-path).

    The scale factor `c` is the MSE-optimal value for the KV cache.
    """

    def __init__(self, c: float = DEFAULT_CONSTANT_C, gs: int | None = None) -> None:
        self.c = c
        self.gs = gs

    def get_group_size(self) -> int:
        return self.gs

    def get_constant_c(self) -> float:
        return self.c

    def get_slot_size(self, head_dim: int) -> int:
        return slot_size(head_dim, self.gs)

    def get_k_codes_offset(self, head_dim: int) -> int:
